resultado("Campo_cityCode", (record.through.delivery.geographicAddress.cityCode != null) and global::poblado(record.through.delivery.geographicAddress.cityCode), "cityCode poblado", "cityCode ausente o incompleto"), resultado("Campo_formattedAddress", (record.through.delivery.geographicAddress.formattedAddress != null) and global::poblado(record.through.delivery.geographicAddress.formattedAddress), "formattedAddress poblado", "formattedAddress ausente o incompleto"),
]
